import os, json, csv, re, sys
import numpy as np

N = 26
P_PROM_KKT = 'storage/prometheus/SOTA_550_kkt_pairs.json'
P_NOE_BOUND = 'storage/noesis/exports/active_boundary_tol1e8.csv'
P_NOE_KKT = 'storage/noesis/exports/shadow_prices_tol1e8.csv'
P_NOE_C = 'storage/noesis/latest_centers.txt'
P_NOE_R = 'storage/noesis/latest_radii.txt'
OUT_SUM = 'storage/noesis/exports/appendix_prometheus_kkt_compare_v2.json'

def load_noesis_snapshot():
    if os.path.exists(P_NOE_C) and os.path.exists(P_NOE_R):
        c = np.loadtxt(P_NOE_C, dtype=float).reshape(N,2)
        r = np.loadtxt(P_NOE_R, dtype=float).reshape(N,)
    else:
        centers = []
        radius = 0.08
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    x = 0.1 + 0.2*i; y = 0.1 + 0.15*j
                    centers.append([x, y])
        c = np.array(centers, float); r = np.full(N, radius, float)
    return c, r

def load_boundary_discs_csv(path):
    discs = set()
    if not os.path.exists(path):
        return discs
    with open(path, 'r', newline='') as f:
        rdr = csv.reader(f)
        header = next(rdr, None)
        idx_disc = None
        if header:
            for k, name in enumerate(header):
                nm = str(name).strip().lower()
                if nm in ('disc','i','index','id','node','circle'):
                    idx_disc = k; break
        else:
            f.seek(0); rdr = csv.reader(f)
        for row in rdr:
            if not row: continue
            if idx_disc is not None:
                try:
                    d = int(row[idx_disc])
                    if 0 <= d < N: discs.add(d)
                    continue
                except Exception:
                    pass
            # fallback: first integer token
            m = re.search(r'-?\d+', ' '.join(row))
            if m:
                d = int(m.group(0))
                if 0 <= d < N: discs.add(d)
    return discs

def load_noesis_kkt_csv(path, boundary_discs):
    pairs = []
    if not os.path.exists(path): return pairs
    with open(path, 'r', newline='') as f:
        try:
            rdr = csv.DictReader(f)
            keys = [k.lower() for k in (rdr.fieldnames or [])]
            key_i = next((k for k in rdr.fieldnames if k and k.lower() in ('i','disc_i','a','idx_i','u')), None)
            key_j = next((k for k in rdr.fieldnames if k and k.lower() in ('j','disc_j','b','idx_j','v')), None)
            key_v = next((k for k in rdr.fieldnames if k and k.lower() in ('lambda','multiplier','value','shadow_price','w')), None)
            if key_i and key_j and key_v:
                for row in rdr:
                    try:
                        i = int(row[key_i]); j = int(row[key_j]); val = float(row[key_v])
                    except Exception:
                        continue
                    if 0 <= i < N and 0 <= j < N and i != j:
                        a,b = (i,j) if i<j else (j,i)
                        if a in boundary_discs or b in boundary_discs: continue
                        pairs.append((a,b,val))
            else:
                f.seek(0); rdr2 = csv.reader(f)
                for row in rdr2:
                    if len(row) < 3: continue
                    try:
                        i, j = int(row[0]), int(row[1]); val = float(row[2])
                    except Exception:
                        continue
                    if 0 <= i < N and 0 <= j < N and i != j:
                        a,b = (i,j) if i<j else (j,i)
                        if a in boundary_discs or b in boundary_discs: continue
                        pairs.append((a,b,val))
        except Exception:
            pass
    best = {}
    for a,b,v in pairs:
        best[(a,b)] = max(v, best.get((a,b), -np.inf))
    out = [(a,b,v) for (a,b),v in best.items()]
    out.sort(key=lambda t: t[2], reverse=True)
    return out

_PAIR_KEY_RE = re.compile(r'[-\[\(\s]*(\d+)\s*[,;:\s]\s*(\d+)[-\]\)\s]*')
def _parse_pair_key_str(k):
    m = _PAIR_KEY_RE.search(str(k))
    if not m: return None
    i, j = int(m.group(1)), int(m.group(2))
    if 0 <= i < N and 0 <= j < N and i != j:
        return (i,j) if i<j else (j,i)
    return None

def _append_pair(pairs, i, j, val, boundary_discs):
    if not (0 <= i < N and 0 <= j < N and i != j): return
    a,b = (i,j) if i<j else (j,i)
    if a in boundary_discs or b in boundary_discs: return
    if not np.isfinite(val): return
    pairs.append((a,b,float(val)))

def load_prometheus_kkt_json(path, boundary_discs):
    pairs = []
    if not os.path.exists(path): return pairs
    try:
        data = json.load(open(path, 'r'))
    except Exception:
        return pairs

    def parse_item(e):
        # Accept dicts with many potential shapes
        if isinstance(e, dict):
            # dict with explicit i,j plus any of lambda/multiplier/value/w
            for ki,kj,kv in (('i','j','lambda'), ('i','j','multiplier'), ('i','j','value'),
                             ('a','b','lambda'), ('u','v','w'), ('i','j','w')):
                if ki in e and kj in e and kv in e:
                    try:
                        _append_pair(pairs, int(e[ki]), int(e[kj]), float(e[kv]), boundary_discs)
                        return
                    except Exception:
                        pass
            # dict with 'pair':[i,j], value under any key
            if 'pair' in e and isinstance(e['pair'], (list,tuple)) and len(e['pair'])>=2:
                i,j = int(e['pair'][0]), int(e['pair'][1])
                for kv in ('lambda','multiplier','value','w'):
                    if kv in e:
                        try:
                            _append_pair(pairs, i, j, float(e[kv]), boundary_discs); return
                        except Exception:
                            pass
            # dict-of-dicts or dict-of-lists: descend one level
            for v in e.values():
                if isinstance(v, (list,dict)):
                    parse_any(v)
            return
        # list or tuple assumed numeric triple [i,j,val]
        if isinstance(e, (list,tuple)) and len(e) >= 3:
            try:
                _append_pair(pairs, int(e[0]), int(e[1]), float(e[2]), boundary_discs); return
            except Exception:
                pass

    def parse_any(obj):
        if isinstance(obj, dict):
            # Handle dict mapping string pair keys to values: {"(i,j)": val}
            count_before = len(pairs)
            for k,v in obj.items():
                key_pair = _parse_pair_key_str(k)
                if key_pair is not None:
                    try:
                        _append_pair(pairs, key_pair[0], key_pair[1], float(v), boundary_discs)
                    except Exception:
                        pass
            # If nothing added, try typical keys or nested structures
            if len(pairs) == count_before:
                # look for common top-level containers
                for key in ('pairs','ranked','data','items','active_pairs','kkt_pairs'):
                    if key in obj:
                        parse_any(obj[key])
                # also parse all values
                for v in obj.values():
                    if isinstance(v, (list,dict)):
                        parse_any(v)
        elif isinstance(obj, list):
            for e in obj:
                parse_item(e)

    parse_any(data)

    # Deduplicate by max value
    best = {}
    for a,b,v in pairs:
        best[(a,b)] = max(v, best.get((a,b), -np.inf))
    out = [(a,b,v) for (a,b),v in best.items()]
    out.sort(key=lambda t: t[2], reverse=True)
    return out

def topk_pairs(sorted_pairs, K):
    return [(a,b) for (a,b,_) in sorted_pairs[:K]]

def jaccard(A, B):
    A = set(A); B = set(B)
    if not A and not B: return 1.0
    return len(A & B) / len(A | B) if (A or B) else 1.0

def main():
    boundary_noe = load_boundary_discs_csv(P_NOE_BOUND)
    noe_kkt = load_noesis_kkt_csv(P_NOE_KKT, boundary_noe)
    prom_kkt = load_prometheus_kkt_json(P_PROM_KKT, boundary_noe)

    K9, K8 = 25, 15
    noe_top9 = topk_pairs(noe_kkt, K9)
    noe_top8 = topk_pairs(noe_kkt, K8)
    prom_top9 = topk_pairs(prom_kkt, K9)
    prom_top8 = topk_pairs(prom_kkt, K8)

    j_top9 = jaccard(noe_top9, prom_top9)
    j_top8 = jaccard(noe_top8, prom_top8)

    summary = {
        "assumptions": {
            "boundary_consensus_tol1e8": True,
            "interior_filter_source": "noesis active_boundary_tol1e8.csv"
        },
        "sources": {
            "prometheus_kkt_json": P_PROM_KKT,
            "noesis_kkt_csv": P_NOE_KKT,
            "noesis_boundary_csv": P_NOE_BOUND
        },
        "counts": {
            "noesis_kkt_pairs": len(noe_kkt),
            "prometheus_kkt_pairs": len(prom_kkt),
            "noesis_top9": len(noe_top9),
            "noesis_top8": len(noe_top8),
            "prometheus_top9": len(prom_top9),
            "prometheus_top8": len(prom_top8)
        },
        "topK": {
            "noesis_top9": noe_top9,
            "noesis_top8": noe_top8,
            "prometheus_top9": prom_top9,
            "prometheus_top8": prom_top8
        },
        "overlaps": {
            "jaccard_top9_kkt": j_top9,
            "jaccard_top8_kkt": j_top8
        }
    }

    os.makedirs(os.path.dirname(OUT_SUM), exist_ok=True)
    with open(OUT_SUM, 'w') as f:
        json.dump(summary, f, indent=2)

    # STDOUT for quick review
    print("[APPENDIX-KKT v2] counts:", summary["counts"])
    print("[APPENDIX-KKT v2] J_top9=", j_top9, "J_top8=", j_top8)
    print("[APPENDIX-KKT v2] out:", OUT_SUM)

    # Return Noesis snapshot for a valid eval
    centers, radii = load_noesis_snapshot()
    radii = np.maximum(radii - 1e-9, 1e-12)
    return centers.astype(float), radii.astype(float)

def construct_packing():
    return main()
